CREATE EXTENSION IF NOT EXISTS pg_trgm;--> statement-breakpoint
-- Hand-added: stop, rather than fail on the seed's unique index, when a live
-- customer tenant already holds the now-reserved slug.
DO $$
BEGIN
  IF EXISTS (SELECT 1 FROM "tenants" WHERE "slug" = 'platform' AND "deleted_at" IS NULL) THEN
    RAISE EXCEPTION 'migration 0016: a live tenant already uses the reserved slug "platform"; rename it before upgrading';
  END IF;
END $$;--> statement-breakpoint
CREATE TABLE "audit_logs" (
	"id" varchar(36) PRIMARY KEY DEFAULT uuidv7() NOT NULL,
	"occurred_at" timestamp (3) with time zone DEFAULT now() NOT NULL,
	"actor_kind" varchar(10) NOT NULL,
	"actor_user_id" varchar(36),
	"access" varchar(10) NOT NULL,
	"tenant_id" varchar(36) NOT NULL,
	"action" varchar(64) NOT NULL,
	"target_type" varchar(32),
	"target_id" varchar(36),
	"metadata" jsonb DEFAULT '{}'::jsonb NOT NULL,
	"request_id" varchar(64),
	"ip" varchar(45),
	"user_agent" varchar(512),
	CONSTRAINT "audit_logs_actor_kind_check" CHECK ("audit_logs"."actor_kind" in ('user', 'system')),
	CONSTRAINT "audit_logs_access_check" CHECK ("audit_logs"."access" in ('member', 'platform', 'system')),
	CONSTRAINT "audit_logs_actor_user_check" CHECK (("audit_logs"."actor_kind" = 'system') = ("audit_logs"."actor_user_id" is null)),
	CONSTRAINT "audit_logs_action_check" CHECK ("audit_logs"."action" ~ '^[a-z]+(\.[a-z_]+)+$'),
	CONSTRAINT "audit_logs_target_type_check" CHECK ("audit_logs"."target_type" is null or "audit_logs"."target_type" in ('tenant', 'membership', 'invitation', 'settings', 'user')),
	CONSTRAINT "audit_logs_target_check" CHECK (("audit_logs"."target_type" is null) = ("audit_logs"."target_id" is null))
);
--> statement-breakpoint
